q80 <- infilled_df %>%
  # select(-tot_disch)%>%
  # left_join(., tots)%>%
  group_by(wyear, local_site) %>%
  arrange(date) %>%
  mutate(cum_discharge = cumsum(discharge)) %>%
  ungroup() %>%
