  summarize(q80 = min(yday), .groups = "drop")

q80_mean <- infilled_df %>%
  # select(-tot_disch)%>%
  # left_join(., tots)%>%
  group_by(wyear, local_site) %>%
  arrange(date) %>%
  mutate(cum_discharge = cumsum(discharge)) %>%
  ungroup() %>%
  left_join(avg_tots) %>%
  rowwise() %>%
  mutate(thresh = ifelse(cum_discharge > disch_80_all, 1, 0)) %>%
