q50 <- q50 %>%
  left_join(., q20) %>%
  left_join(., q80) %>%
  left_join(., q50_mean) %>%
  left_join(., q20_mean) %>%
  left_join(., q80_mean) %>%
  mutate(duration = q80 - q20) %>%
  mutate(duration_mean = q80_mean - q20_mean)

ggplot(q50, aes(x = wyear, y = q50, color = prop_infilled)) +
  geom_point() +
  geom_smooth(method = "lm") +
  facet_wrap(~local_site) +
  ggtitle("q50 over time")

# are the wyears complete
cts = infilled_df%>%
  group_by(local_site, wyear) %>%
  summarize(n = dplyr::n())

# yes except albion 1981 and a few
# days of saddle in the last year after it was already 0

# make all into anomalies, by month or not
anom_disch <- infilled_df%>%
  filter(wyear >1981&wyear<2025) %>%
group_by(local_site, wyear) %>%
  summarise(
    total_disch = sum(discharge),
    ct = dplyr::n())%>%
  ungroup()%>%
  group_by(local_site) %>%
  mutate(avgdisch = mean(total_disch, na.rm = TRUE),
    anom_disch = total_disch *100/avgdisch -100,
    posneg = ifelse(anom_disch > 0, "pos", "neg") %>%
      factor(c("pos", "neg"))) %>%
  ungroup()


facet_names <-  c(alb = "Albion",
                  gl4 = "Green Lake 4",
                  mar = "Martinelli",
                  sdl = "Saddle")

row_label_sites <- c("gl4", "sdl")  # rightmost panel of each row

x_range <- range(anom_disch$wyear, na.rm = TRUE)

row_labels <- data.frame(
  local_site = row_label_sites,
  x = x_range[2] + diff(x_range) * 0.1,
  y = 0,
  label = "more~flow  %<->%  less~flow"
)

g1 <- ggplot(anom_disch , aes(x = wyear, y = anom_disch)) +
  geom_col(aes(fill = posneg)) +
  scale_fill_manual(values = c("#023E8A", "#E9A21B")) +
  labs(
    y = "Streamflow <br> (% difference from long-term mean)",
    x = "Year"
  ) +
  scale_x_continuous(
    breaks = seq(
      10 * floor(min(anom_disch$wyear) / 10),
      10 * ceiling(max(anom_disch$wyear) / 10),
      by = 10
    ),
    minor_breaks = seq(
      5 * floor(min(anom_disch$wyear) / 5),
      5 * ceiling(max(anom_disch$wyear) / 5),
      by = 5
    ),
    guide = guide_axis(minor.ticks = TRUE)
  ) +
  scale_y_symmetric() +
  geom_text(
    data = row_labels,
    aes(x = x, y = y, label = label),
    angle = -90, hjust = 0.5, vjust = 0.5, size = 2.5, inherit.aes = FALSE,
    parse = TRUE
  ) +
  theme_hc() +
  facet_wrap(~local_site, scales = 'free_y',
             labeller = as_labeller(facet_names))+
  theme(
    legend.position = "none",
    axis.minor.ticks.length = rel(0.5),
    axis.title.y = element_markdown(),
    plot.margin = margin(t = 5.5, r = 25, b = 5.5, l = 5.5)
  ) +
  coord_cartesian(xlim = x_range, clip = "off")

ggsave(g1,
       file = file.path(figures_dir, "streamflow_anom.png"),
       scale = 0.6, width = 10, height = 6
)


#### Visualizing anomalies in streamflow from Green Lake 4 by month###
# make all into anomalies, by month or not

anom_disch_month_gl4 <- infilled_df%>%
  filter(local_site == 'gl4'&wyear<2025) %>%
  mutate(month = lubridate::month(date)) %>%
  filter(month %in% c(5:9)) %>%
  group_by(wyear, month) %>%
  summarise(
    total_disch = sum(discharge))%>%
  ungroup()%>%
  group_by(month) %>%
  mutate(avgdisch = mean(total_disch, na.rm = TRUE),
         anom_disch = total_disch *100/avgdisch -100,
         posneg = ifelse(anom_disch > 0, "pos", "neg") %>%
           factor(c("pos", "neg"))) %>%
  ungroup() %>%
  mutate(month_name = 
           month(month, label=TRUE))

#Step 2: make figure
anom_disch_month_gl4 <- anom_disch_month_gl4 %>%
  mutate(month_name = factor(month_name, levels = c("May", "Jun", "Jul", "Aug", "Sep"), ordered = TRUE))

x_range_month <- range(anom_disch_month_gl4$wyear, na.rm = TRUE)

row_labels_month <- data.frame(
  month_name = factor(c("Jul", "Sep"), levels = c("May", "Jun", "Jul", "Aug", "Sep"), ordered = TRUE),
  x = x_range_month[2] + diff(x_range_month) * 0.1,
  y = 0,
